import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('returns a ToolResponse naming the missing required field and does not invoke the executor', async () => {
    let executorCalls = 0;
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const toolResponse = await registry.execute('weather', {});

    expect({toolResult: toolResponse.result, executorCalls}).toEqual({
      toolResult: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: 0,
    });
  });

  it('compiles a static schema once at registration', async () => {
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'get weather', inputSchema},
      async input => `sunny in ${String(input.location)}`
    );

    const locationSchema = inputSchema.properties.location as {type: string};
    locationSchema.type = 'not-a-json-schema-type';

    await expect(registry.execute('weather', {location: 'Paris'})).resolves.toEqual({result: 'sunny in Paris'});
  });

  it('retains the schema compilation error as the registration error cause', () => {
    const registry = new ToolRegistry();

    try {
      registry.register(
        {
          name: 'broken',
          description: 'invalid schema',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-type'}}},
        },
        async () => 'unreachable'
      );
      throw new Error('expected registration to fail');
    } catch (error) {
      expect(error).toEqual(
        expect.objectContaining({
          message: expect.stringContaining("Failed to compile inputSchema for tool 'broken'"),
          cause: expect.any(Error),
        })
      );
    }
  });

  it('validates each call against the current function-valued schema', async () => {
    let useLocationSchema = true;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'weather',
        description: 'get weather',
        inputSchema: useLocationSchema
          ? {type: 'object', required: ['location'], properties: {location: {type: 'string'}}}
          : {type: 'object', required: ['units'], properties: {units: {type: 'string'}}},
      }),
      async input => `received ${Object.keys(input).join(',')}`
    );

    const firstResponse = await registry.execute('weather', {location: 'Paris'});
    useLocationSchema = false;
    const secondResponse = await registry.execute('weather', {location: 'Paris'});

    expect({firstResponse, secondResponse}).toEqual({
      firstResponse: {result: 'received location'},
      secondResponse: {result: expect.stringMatching(/units.*required|required.*units/i)},
    });
  });

  it('rejects an enum value with its field and constraint without exposing the value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', properties: {units: {enum: ['celsius', 'fahrenheit']}}},
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {units: 'kelvin'});

    expect({result: response.result, leaksValue: response.result.includes('kelvin')}).toEqual({
      result: expect.stringMatching(/units.*enum|enum.*units/i),
      leaksValue: false,
    });
  });
});
