import {ToolRegistry} from './registry.js';
import {createChatOrchestrator} from '../chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {AIProvider, MessageChunk, SendMessageParams, ToolResultMessage} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

describe('ToolRegistry inputSchema validation acceptance', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsField: response.result.includes('ssn'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('123456789'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      }),
      async input => {
        executorInputs.push(input);
        return `22C in ${String(input.location)}`;
      }
    );

    let firstRoundToolResult = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (round !== 2) {
          yield {type: 'text', text: '22C in Paris'};
          yield {type: 'stop', stopReason: 'end_turn'};
          return;
        }
        const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
        const firstResult = lastMessage.content[0];
        firstRoundToolResult = firstResult?.content ?? '';
        yield {
          type: 'tool_use',
          toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
        };
        yield {type: 'stop', stopReason: 'tool_use'};
        return;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      registry
    );
    const session: ChatSession = {
      sessionId: 's-retry',
      userId: 'u1',
      entries: [{role: 'user', content: 'Weather in Paris?', timestamp: SENT_AT}],
    };

    const reply = await orchestrator.processMessage(session);

    expect({
      reply,
      executorInputs,
      firstAttemptRejectedForLocation:
        firstRoundToolResult.includes('location') && /required/i.test(firstRoundToolResult),
    }).toEqual({
      reply: '22C in Paris',
      executorInputs: [{location: 'Paris'}],
      firstAttemptRejectedForLocation: true,
    });
  });
});
export interface Logger {
  debug(category: string, message: string, fields?: Record<string, unknown>): void;
  info(category: string, message: string, fields?: Record<string, unknown>): void;
  warn(category: string, message: string, fields?: Record<string, unknown>): void;
  error(category: string, message: string, fields?: Record<string, unknown>): void;
}

const LOG_LEVELS = {DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3} as const;
type LevelName = keyof typeof LOG_LEVELS;

const METHODS = {DEBUG: 'debug', INFO: 'info', WARN: 'warn', ERROR: 'error'} as const;

const resolvedLevel = (() => {
  const env = (process.env.LOG_LEVEL || 'info').toUpperCase();
  return LOG_LEVELS[env as LevelName] ?? LOG_LEVELS.INFO;
})();

export const UNSERIALISABLE = '[unserialisable]';

function emit(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
  // Caller fields are nested under `data`, so one named `severity` cannot overwrite the line's own.
  const line = {
    severity: level,
    message,
    timestamp: new Date().toISOString(),
    category,
    ...(fields ? {data: fields} : {}),
  };

  // ERROR to stderr: a stream that cannot be split by severity cannot be alerted on.
  // eslint-disable-next-line no-console -- the one place this package writes to a stream
  (level === 'ERROR' ? console.error : console.log)(serialise(line));
}

// A throw here would take down the call site being observed, so an unserialisable field costs that field alone.
function serialise(line: Record<string, unknown>): string {
  const whole = probe(() => JSON.stringify(line));
  if (whole.ok) return whole.value;

  // String() runs the caller's toString, so it is attempted inside the probe rather than before it.
  const degraded = probe(() =>
    JSON.stringify({
      severity: line.severity,
      message: String(line.message),
      timestamp: line.timestamp,
      category: String(line.category),
      data: `${UNSERIALISABLE}: ${whole.reason}`,
    })
  );
  if (degraded.ok) return degraded.value;

  // Nothing the caller supplied survives into this one, so it cannot fail in turn.
  return JSON.stringify({
    severity: line.severity,
    message: UNSERIALISABLE,
    timestamp: line.timestamp,
    category: UNSERIALISABLE,
    data: `${UNSERIALISABLE}: ${degraded.reason}`,
  });
}

// A probe, not control flow: it reports what happened rather than branching on a swallowed error.
function probe(run: () => string): {ok: true; value: string} | {ok: false; reason: string} {
  try {
    return {ok: true, value: run()};
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return {ok: false, reason: reason.split('\n')[0]};
  }
}

const consoleLogger: Logger = {
  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('DEBUG', category, message, fields),
  info: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('INFO', category, message, fields),
  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('WARN', category, message, fields),
  error: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('ERROR', category, message, fields),
};

let active: Logger = consoleLogger;

// Process-global by design: every module that logs imports `log` at module scope, so there is one.
export function setLogger(logger?: Logger): void {
  // Handed `log` itself, the delegate below would call itself until the stack ran out, so that reads as none.
  active = logger === undefined || logger === log ? consoleLogger : logger;
}

// The one place a level is tested, so LOG_LEVEL gates a supplied logger exactly as it gates the built-in one.
function dispatch(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
  if (LOG_LEVELS[level] < resolvedLevel) return;

  const delivered = probe(() => {
    active[METHODS[level]](category, message, fields);
    return '';
  });
  if (delivered.ok) return;

  // A supplied logger that throws must not take down the call site it observes, and the line is not dropped.
  probe(() => {
    emit(level, category, message, fields);
    return '';
  });
}

// Delegating rather than reassigned, so a module that imported `log` before the swap still sees it.
export const log: Logger = {
  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('DEBUG', category, message, fields),
  info: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('INFO', category, message, fields),
  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('WARN', category, message, fields),
  error: (category: string, message: string, fields?: Record<string, unknown>) =>
    dispatch('ERROR', category, message, fields),
};
